#!/usr/bin/env bash
# M4-05: RDS Postgres + its Secrets Manager secret (paid layer: db.t4g.micro ~$0.016/h + storage).
#   infra/rds.sh up      first run: create secret + subnet group + DB. Later runs: start the DB if stopped
#   infra/rds.sh down    stop the DB (no instance-hours billed; storage still is)
#   infra/rds.sh status
#
# The secret taskflow/prod/db holds {host, port, dbname, username, password} (ARCHITECTURE §3.3).
# The password is generated by Secrets Manager and never printed, logged or committed.
# NOTE: AWS automatically restarts a stopped RDS instance after 7 days. Run `down` again if needed.
set -euo pipefail
# shellcheck source-path=SCRIPTDIR
# shellcheck source=lib.sh
source "$(dirname "$0")/lib.sh"

action="${1:-status}"
require_aws

db_status() {
  q aws rds describe-db-instances --db-instance-identifier "$DB_ID" \
    --query 'DBInstances[0].DBInstanceStatus' --output text 2>/dev/null || true
}

wait_for_status() {
  local want="$1" s
  log "Waiting for $DB_ID to be $want (RDS is slow: 5-15 minutes)"
  while true; do
    s="$(db_status)"
    [[ "$s" == "$want" ]] && break
    printf '  %s: %s\n' "$(date +%H:%M:%S)" "${s:-missing}" >&2
    sleep 30
  done
}

ensure_secret() {
  if aws secretsmanager describe-secret --secret-id "$DB_SECRET" >/dev/null 2>&1; then
    log "Secret exists: $DB_SECRET"
    return
  fi
  log "Creating secret $DB_SECRET with a generated password"
  local pw
  pw="$(aws secretsmanager get-random-password --password-length 32 --exclude-punctuation \
    --query RandomPassword --output text)"
  aws secretsmanager create-secret --name "$DB_SECRET" \
    --description "TaskFlow RDS connection (read by EC2 user-data)" \
    --tags "Key=Project,Value=$PROJECT" "Key=Owner,Value=$OWNER_TAG" \
    --secret-string "$(jq -nc --arg u "$DB_USER" --arg p "$pw" --arg d "$DB_NAME" \
      '{host: "", port: 5432, dbname: $d, username: $u, password: $p}')" >/dev/null
}

ensure_subnet_group() {
  if aws rds describe-db-subnet-groups --db-subnet-group-name "$DB_SUBNET_GROUP" >/dev/null 2>&1; then
    return
  fi
  local vpc_id priv_a priv_b
  vpc_id="$(find_vpc_id)"
  [[ -n "$vpc_id" ]] || die "$VPC_NAME not found. Run infra/01-network.sh first"
  priv_a="$(q aws ec2 describe-subnets --filters "Name=tag:Name,Values=$SUBNET_PRIVATE_A" \
    "Name=vpc-id,Values=$vpc_id" --query 'Subnets[0].SubnetId' --output text)"
  priv_b="$(q aws ec2 describe-subnets --filters "Name=tag:Name,Values=$SUBNET_PRIVATE_B" \
    "Name=vpc-id,Values=$vpc_id" --query 'Subnets[0].SubnetId' --output text)"
  log "Creating DB subnet group $DB_SUBNET_GROUP ($SUBNET_PRIVATE_A, $SUBNET_PRIVATE_B)"
  aws rds create-db-subnet-group --db-subnet-group-name "$DB_SUBNET_GROUP" \
    --db-subnet-group-description "TaskFlow private subnets in 2 AZs" \
    --subnet-ids "$priv_a" "$priv_b" \
    --tags "Key=Project,Value=$PROJECT" "Key=Owner,Value=$OWNER_TAG" >/dev/null
}

create_db() {
  local vpc_id db_sg version pw
  vpc_id="$(find_vpc_id)"
  db_sg="$(q aws ec2 describe-security-groups --filters "Name=group-name,Values=$SG_DB" \
    "Name=vpc-id,Values=$vpc_id" --query 'SecurityGroups[0].GroupId' --output text)"
  [[ -n "$db_sg" ]] || die "$SG_DB not found. Run infra/02-security-groups.sh first"
  version="$(aws rds describe-orderable-db-instance-options --engine postgres --db-instance-class "$DB_CLASS" \
    --query "OrderableDBInstanceOptions[?starts_with(EngineVersion,'$DB_MAJOR.')].EngineVersion" \
    --output text | tr '\t' '\n' | sort -uV | tail -1)"
  [[ -n "$version" ]] || die "no Postgres $DB_MAJOR.x available for $DB_CLASS"
  pw="$(aws secretsmanager get-secret-value --secret-id "$DB_SECRET" \
    --query SecretString --output text | jq -r .password)"
  log "Creating RDS $DB_ID: Postgres $version, $DB_CLASS, 20 GB gp3, private, single-AZ, encrypted"
  aws rds create-db-instance \
    --db-instance-identifier "$DB_ID" \
    --engine postgres --engine-version "$version" \
    --db-instance-class "$DB_CLASS" \
    --allocated-storage 20 --storage-type gp3 --storage-encrypted \
    --db-name "$DB_NAME" --master-username "$DB_USER" --master-user-password "$pw" \
    --db-subnet-group-name "$DB_SUBNET_GROUP" --vpc-security-group-ids "$db_sg" \
    --no-publicly-accessible --no-multi-az \
    --backup-retention-period 1 --copy-tags-to-snapshot \
    --deletion-protection --auto-minor-version-upgrade \
    --tags "Key=Name,Value=$DB_ID" "Key=Project,Value=$PROJECT" "Key=Owner,Value=$OWNER_TAG" >/dev/null
}

# Writes the current endpoint into the secret if it changed.
sync_secret_host() {
  local endpoint current
  endpoint="$(aws rds describe-db-instances --db-instance-identifier "$DB_ID" \
    --query 'DBInstances[0].Endpoint.Address' --output text)"
  current="$(aws secretsmanager get-secret-value --secret-id "$DB_SECRET" --query SecretString --output text)"
  if [[ "$(jq -r .host <<<"$current")" != "$endpoint" ]]; then
    aws secretsmanager put-secret-value --secret-id "$DB_SECRET" \
      --secret-string "$(jq -c --arg h "$endpoint" '.host = $h' <<<"$current")" >/dev/null
    log "Secret $DB_SECRET: host = $endpoint"
  fi
}

case "$action" in
  up)
    ensure_secret
    ensure_subnet_group
    case "$(db_status)" in
      "")        create_db ;;
      stopped)   log "Starting $DB_ID"; aws rds start-db-instance --db-instance-identifier "$DB_ID" >/dev/null ;;
      available) log "$DB_ID already available" ;;
      *)         log "$DB_ID is $(db_status)" ;;
    esac
    wait_for_status available
    sync_secret_host
    log "RDS up: $(aws rds describe-db-instances --db-instance-identifier "$DB_ID" \
      --query 'DBInstances[0].[EngineVersion,Endpoint.Address]' --output text)"
    ;;
  down)
    case "$(db_status)" in
      available) log "Stopping $DB_ID"; aws rds stop-db-instance --db-instance-identifier "$DB_ID" >/dev/null
                 wait_for_status stopped ;;
      stopped)   log "$DB_ID already stopped" ;;
      "")        log "$DB_ID does not exist" ;;
      *)         die "$DB_ID is $(db_status); try again when it is available" ;;
    esac
    log "RDS down. Instance hours stopped (storage still billed, ~\$0.08/GB-month). Auto-restarts after 7 days."
    ;;
  status)
    s="$(db_status)"
    echo "RDS $DB_ID: ${s:-does not exist}"
    ;;
  *)
    die "usage: $0 up|down|status"
    ;;
esac
